export default function prepare({ body, recipient }) {
  const m = body?.message,
    d = m?.document;
  if (
    !m ||
    !Number.isSafeInteger(m.message_id) ||
    m.message_id <= 0 ||
    !Number.isSafeInteger(m.chat?.id)
  )
    throw Error("Telegram message has no chat or message ID");
  const base = { chatId: String(m.chat.id), replyId: m.message_id, recipients: [recipient] };
  if (!d || typeof d !== "object" || Array.isArray(d))
    return {
      ...base,
      hasDocument: false,
      fileId: "-",
      fileRequest: {},
      fileName: "",
      mimeType: "application/octet-stream",
    };
  if (
    typeof recipient !== "string" ||
    !/^\S+@\S+\.\S+$/.test(recipient) ||
    recipient.startsWith("YOUR_")
  )
    throw Error("Set the destination email address");
  if (typeof d.file_id !== "string" || !d.file_id) throw Error("Missing Telegram file ID");
  return {
    ...base,
    hasDocument: true,
    fileId: d.file_id,
    fileRequest: { file_id: d.file_id },
    fileName: typeof d.file_name === "string" ? d.file_name : "",
    mimeType:
      typeof d.mime_type === "string" && d.mime_type ? d.mime_type : "application/octet-stream",
  };
}

