import { Buffer } from "node:buffer";
export default async function download(
  { botToken, verified, reply, statusCode, fileId, fileName, mimeType },
  context,
) {
  if (verified !== true || typeof botToken !== "string" || !/^\d+:[A-Za-z0-9_-]+$/.test(botToken))
    throw Error("Verify the Telegram bot token before downloading");
  const file = reply?.result,
    path = file?.file_path;
  if (
    statusCode !== 200 ||
    reply?.ok !== true ||
    file?.file_id !== fileId ||
    typeof path !== "string" ||
    !path ||
    path.startsWith("/") ||
    path.split("/").some((x) => !x || x === "." || x === "..") ||
    /[?#\\\x00-\x20]/.test(path)
  )
    throw Error("Telegram did not confirm a valid downloadable document");
  const name = fileName || path.split("/").at(-1);
  if (!name) throw Error("Missing document name");
  try {
    const r = await context.fetch(
      "https://api.telegram.org/file/bot" +
        botToken +
        "/" +
        path.split("/").map(encodeURIComponent).join("/"),
      { method: "GET" },
    );
    if (!r.ok) throw Error("Download failed");
    const bytes = new Uint8Array(await r.arrayBuffer());
    if (
      typeof file.file_size === "number" &&
      (!Number.isSafeInteger(file.file_size) ||
        file.file_size < 0 ||
        file.file_size !== bytes.length)
    )
      throw Error("Size mismatch");
    return {
      name,
      mimeType,
      contentBase64: Buffer.from(bytes).toString("base64"),
      mailBody: `This is a book named  ${name} from telegram bot.`,
    };
  } catch {
    throw Error("Telegram document download failed; no draft was created");
  }
}

