export default function attachment({ draft, name, mimeType, contentBase64 }) {
  const id = draft?.id;
  if (typeof id !== "string" || !id)
    throw Error("Outlook did not confirm draft ID; inspect drafts before retrying");
  return {
    id,
    endpoint: "/me/messages/" + encodeURIComponent(id) + "/attachments",
    body: {
      "@odata.type": "#microsoft.graph.fileAttachment",
      name,
      contentType: mimeType,
      contentBytes: contentBase64,
    },
  };
}

